define("ActivityMiniPage", ["ConferenceRoomMixin"], function() {
	return {
		entitySchemaName: "Activity",
		mixins: {
			ConferenceRoomMixin: Terrasoft.ConferenceRoomMixin
		},
		attributes: {
			"ConferenceRoom": {
				"dataValueType": this.Terrasoft.DataValueType.LOOKUP,
				"lookupListConfig": {
					"filters": [
						function() {
							return this.getFreeConferenceRoomFilter();
						}
					]
				},
				"dependencies": [
					{
						columns: ["ConferenceRoom"],
						methodName: "loadCurrentConferenceRoomSchedule"
					}
				]
			},
			"ConferenceRoomSchedule": {
				dataValueType: Terrasoft.DataValueType.COLLECTION,
				type: Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				isCollection: true,
				value: Ext.create("Terrasoft.ObjectCollection")
			}
		},
		methods: {
			init: function() {
				var schedule = this.get("ConferenceRoomSchedule");
				schedule.clear();
				this.callParent(arguments);
			},

			onEntityInitialized: function() {
				this.callParent(arguments);
				this.loadCurrentConferenceRoomSchedule();
			},

			setValidationConfig: function() {
				this.callParent(arguments);
				this.addColumnValidator("StartDate", this.startDateValidator);
				this.addColumnValidator("DueDate", this.dueDateValidator);
			}
		},
		diff: /**SCHEMA_DIFF*/[
			{
				"operation": "insert",
				"name": "ConferenceRoomEditMode",
				"parentName": "MiniPage",
				"propertyName": "items",
				"values": {
					"bindTo": "ConferenceRoom",
					"contentType": this.Terrasoft.ContentType.ENUM,
					"layout": {
						"column": 0,
						"row": 11,
						"colSpan": 24
					},
					"visible": {
						"bindTo": "isNotViewMode"
					}
				}
			},
			{
				"operation": "insert",
				"name": "ConferenceRoomInfoContainer",
				"parentName": "MiniPage",
				"propertyName": "items",
				"values": {
					"itemType": this.Terrasoft.ViewItemType.CONTAINER,
					"items": [],
					"layout": {
						"column": 0,
						"row": 3,
						"colSpan": 24
					}
				}
			},
			{
				"operation": "insert",
				"parentName": "ConferenceRoomInfoContainer",
				"propertyName": "items",
				"name": "ConferenceRoom",
				"values": {
					"labelConfig": {
						"visible": false
					},
					"bindTo": "ConferenceRoom",
					"isMiniPageModelItem": true,
					"visible": {
						"bindTo": "isViewMode"
					}
				}
			}
		]/**SCHEMA_DIFF*/
	};
});

 define("ActivityMiniPage", ["JoinLinkGenerationMixin", "css!JoinLinkGenerationMixin"], function() {
