					}
				},
				"index": 3
			}
		]/**SCHEMA_DIFF*/
	};
});

define("ActivityMiniPage", [], function() {
	return {
		entitySchemaName: "Activity",
		details: /**SCHEMA_DETAILS*/{}/**SCHEMA_DETAILS*/,
		methods: {
			/**
			 * Returns sign of visibility.
			 * @return {Boolean} True if is not SSP user.
			 */
			getOpenCurrentEntityPageVisible: function() {
				return !this.Terrasoft.isCurrentUserSsp();
			},

			/**
			 * @inheritDoc Terrasoft.EntityConnectionLinksUtilities#loadEntityConnectionsByESQ
			 * @override
			 */
			loadEntityConnectionsByESQ: function (esq) {
				if (this.Terrasoft.isCurrentUserSsp()) {
					this._removeUnnecessaryFiltersFromQuery(esq);
				}
				this.callParent(arguments);
			},

			/**
			 * @inheritDoc Terrasoft.EntityConnectionLinksUtilities#addEntityConnectionsColumns
			 * @override
			 */
			addEntityConnectionsColumns: function(esq) {
				this.callParent(arguments);
				if (this.Terrasoft.isCurrentUserSsp()) {
					esq.columns.removeByKey("SysSchemaName");
					esq.addParameterColumn(this.entitySchemaName, this.Terrasoft.DataValueType.TEXT, "SysSchemaName");
				}
			},

			/**
			 * @inheritDoc Terrasoft.EntityConnectionLinksUtilities#processEntityConnectionsResponse
			 * @override
			 */
			processEntityConnectionsResponse: function(collection) {
				if (this.Terrasoft.isCurrentUserSsp()) {
					const filtered = collection.filterByFn(function(entityConnection) {
						const schemaName = entityConnection.$ReferenceSchema && entityConnection.$ReferenceSchema.name;
						return schemaName && this.isNotEmpty(this.getEntityStructure(schemaName));
					}, this);
					collection.reloadAll(filtered);
				}
				this.callParent(arguments);
			},

			/**
			 * @private
			 */
			_removeUnnecessaryFiltersFromQuery: function(esq) {
				esq.filters.removeByKey("EntitySchema");
				esq.filters.removeByKey("SysWorkspace");
			}
		},
		diff: /**SCHEMA_DIFF*/[
			{
				"operation": "merge",
				"name": "OpenCurrentEntityPage",
				"values": {
					"visible": {
						"bindTo": "getOpenCurrentEntityPageVisible"
					}
				}
			}
		]/**SCHEMA_DIFF*/
	};
});

define("ActivityMiniPage", ["ServiceHelper", "BaseFiltersGenerateModule", "css!WorkActivityMiniPageCSS"],function(ServiceHelper,
		BaseFiltersGenerateModule) {
	return {
		entitySchemaName: "Activity",
		attributes: {
			/**
			 * * Activity entity owner column.
			 *
			 */
			"Owner": {
				"type": this.Terrasoft.ViewModelColumnType.ENTITY_COLUMN,
				"lookupListConfig": {
					"filter": BaseFiltersGenerateModule.OwnerFilter
				}
			},
			/**
			/**
			 * Заголовок
			 */
			"Title": {
				dependencies: [
					{
						columns: ["JiraURL"],
						methodName: "onJiraUrlChanged"
					}
				]
			}
		},
		methods: {
			/**
			 * @inheritdoc Terrasoft.BaseMiniPage#init
			 * @overridden
			 */
			processExecDataCallback: function(request, success, response) {
				this.callParent(arguments);
				if (success && response && response.responseText) {
					var processData = this.Ext.decode(this.Ext.decode(response.responseText));
					if (processData) {
						this.initProcessAction(processData);
					}
				}
				this.setTheOnlyProcessResult();
			},

			initProcessAction: function(processData) {
				var defValues = processData && processData.defaultValues;
				if (defValues && defValues.ProcessAction) {
					var processAction = defValues.ProcessAction;
					var params = processAction.split(",");
					var functionName = params.shift();
					if (typeof this[functionName] === "function") {
						this[functionName].apply(this, params);
					}
				}
			},

			setTheOnlyProcessResult: function() {
				var allowedResults = this.get("AllowedResults");
				if (this.getIsFeatureEnabled("TheOnlyActivityProcessResult") && allowedResults) {
					var decodedAllowedResults = this.Ext.decode(allowedResults);
					if (decodedAllowedResults?.length === 1) {
						const theOnlyResult = {
							value: decodedAllowedResults[0].resultId,
							displayValue: decodedAllowedResults[0].caption
						}
						if (!this.$Result) {
							this.$Result = theOnlyResult;
						}
						if (!this.$ProcessResult) {
							this.$ProcessResult = theOnlyResult;
						}
					}
				}
			},

			/**
			 * Returns an instance of the entity connection configuration element.
			 * @protected
			 * @param {String} columnName Entity connection name.
			 * @return {Object} Instance of the entity connection configuration element.
			 */
			getEntityConnectionItemConfig: function(columnName) {
				var entityConnectionName = this.getEntityConnectionName(columnName);
				var entityConnectionItem = [];
				entityConnectionItem.push(this.getEntityConnectionImage(columnName));
				if (!Ext.isEmpty(entityConnectionName)) {
					entityConnectionItem.push(this.getEntityConnectionHyperlink(columnName, entityConnectionName));
				}
				else {
					entityConnectionItem.push(this.getWorkEntityConnectionHyperlink(columnName));
				}
				var connectionModelItem = this.getEntityConnectionModelItem(columnName);
				if (columnName === "JiraURL") {
					connectionModelItem.dataValueType = Terrasoft.DataValueType.TEXT;
					delete connectionModelItem.controlConfig.cleariconclick;
					delete connectionModelItem.controlConfig.prepareList;
					delete connectionModelItem.controlConfig.list;
				}
				entityConnectionItem.push(connectionModelItem);
				if (this.hasCommunications(columnName)) {
					entityConnectionItem.push(this.getEntityConnectionCommunications(columnName));
				}
				return entityConnectionItem;
			},
			getWorkEntityConnectionHyperlink: function(columnName) {
				return {
					"itemType": this.Terrasoft.ViewItemType.HYPERLINK,
					"caption": this.get(columnName),
					"href": this.get(columnName),
					"markerValue": columnName,
					"target": this.Terrasoft.controls.HyperlinkEnums.target.BLANK,
					"classes": {"hyperlinkClass": ["entity-connection-hyperlink"]},
					"click": {"bindTo": "close"},
					"afterrender": {"bindTo": "adjustMiniPagePosition"},
					"afterrerender": {"bindTo": "adjustMiniPagePosition"},
					"visible": {
						"bindTo": "isViewMode"
					}
				};
			},
			tryGetJiraSummary: function(method, scope) {
				return function() {
					var parrentArguments = arguments;
					var title = this.get("Title");
					if (title) {
						this.getJiraSummary(title.trim(), function(result) {
							this.bindJiraWithActivity(this.Ext.apply(result, {onSave: true}));
							method.apply(scope, parrentArguments);
						});
					} else {
						method.apply(scope, parrentArguments);
					}
				};
			},
			/**
			 * Если получен Jira summary то связать Jira с активностью.
			 * @protected
			 * @param {Object} result результат сервиса JiraUtilsService.
			 */
			bindJiraWithActivity: function(result) {
				if (result && result.jiraSummary && result.jiraCode) {
					var jiraCode = result.jiraCode;
					var jiraSummary = result.jiraSummary;
					var titleTemplate = "#{0}\n{1}/browse/{2}\n{3}";
					var jiraTitle = Ext.String.format(titleTemplate, jiraCode, this.$jiraHostUrl, jiraCode, jiraSummary);
					if (result.onSave) {
						this.set("JiraURL", jiraCode);
						this.set("Title", jiraTitle);
					} else {
						var title = this.get("Title");
						if (title) {
							this.showConfirmationDialog(
									this.get("Resources.Strings.ChangeTitleByJiraUrl"),
									function(dialogResult) {
										if (dialogResult === this.Terrasoft.MessageBoxButtons.YES.returnCode) {
											this.set("Title", jiraTitle);
										}
									}, ["yes", "no"]);
						} else {
							this.set("Title", jiraTitle);
						}
					}
				}
			},
			/**
			 * При прохождении Заголовка по маске RegExp вызов сервиса получения заголовка Jira.
			 * @protected
			 * @param {String} jiraCode Код Jira Issue.
			 * @param {Function} callback Функция обратного вызова.
			 */
			getJiraSummary: function(jiraCode, callback) {
				var regExp = new RegExp("^[A-z]+\-[0-9]+$");
				if (!regExp.test(jiraCode)) {
					callback.call(this, {});
					return;
				}
				ServiceHelper.callService({
					serviceName: "JiraUtilsService",
					methodName: "GetTaskSummary",
					data: {taskKey: jiraCode},
					scope: this,
					callback: function(response) {
						var errorCode = response.status || response.GetTaskSummaryResult.errorCode;
						var result;
						if (!errorCode) {
							result = response.GetTaskSummaryResult;
						}
						callback.call(this, {
							jiraSummary: (result && result.summary) ? result.summary : null,
							jiraCode: jiraCode
						});
					}
				});
			},
			/**
			 * Происходит на изменении поля JiraURL.
			 * @protected
			 */
			onJiraUrlChanged: function() {
				var jiraUrl = this.get("JiraURL");
				if (!jiraUrl) {
					return;
				}
				jiraUrl = jiraUrl.split("/");
				if (!jiraUrl.length) {
					return;
				}
				jiraUrl = jiraUrl[jiraUrl.length - 1];
				this.getJiraSummary(jiraUrl, this.bindJiraWithActivity.bind(this));
			},

			init: function() {
				this.initJiraHostUrl();
				this.callParent(arguments);
			},
		
			initJiraHostUrl: function() {
				this.Terrasoft.SysSettings.querySysSettingsItem("JiraHostUrl", function(jiraHostUrl) {
					this.set("jiraHostUrl", jiraHostUrl);
				}, this);
			}

		},
		diff: /**SCHEMA_DIFF*/[
			{
				"operation": "insert",
				"name": "Confirmed",
				"parentName": "MiniPage",
				"propertyName": "items",
				"values": {
					"layout": {
						"colSpan": 24,
						"rowSpan": 1,
						"column": 0,
						"row": 10
					},
					"visible": {
						"bindTo": "isNotViewMode"
					},
					"classes": {
						"wrapClassName": ["activity-mini-page-confirmed"]
					}
				}
			}
		]/**SCHEMA_DIFF*/
	};
});

 define("ActivityMiniPage", ["WorkPRMBaseConstants", "BusinessRuleModule", "OpportunityPartnerWinnerMixin", "ConfigurationItemGenerator",
 	"FileUploadErrorHandlers", "ConfigurationFileApi", "SACaseModalBoxMixin", "WorkActivityPageMixin", "css!SACaseModalBoxMixin", "css!WorkActivityMiniPageCSS"],function(WorkPRMBaseConstants, BusinessRuleModule) {
	return {
		entitySchemaName: "Activity",
		messages: {
			"NeedToSelectOpportunityPartnerWinner": {
				mode: Terrasoft.MessageMode.BROADCAST,
				direction: this.Terrasoft.MessageDirectionType.PUBLISH
			}
		},
		attributes: {
			"Opportunity": {
				"lookupListConfig": {
					"columns": ["Partner"]
				}
			},
			"OpportunityForecast": {
				"lookupListConfig": {
					"columns": ["StartDate"]
				}
			},
			"IsOpenEditModeVisible": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"IsWinnerSelected": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"IsStartDateVisible": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"ProcessResult": {
				onChange: "onProcessResultChanged"
			},
			"Result": {
				onChange: "onResultChanged"
			},
			"ActivityCategory": {
				onChange: "onActivityCategoryChanged"
			},
			"IsArProcessAndPaymentIssues": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"IsDetailedResultArProcessVisible": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"IsArProcess": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"IsExpectedPaymentDateVisibleAndRequired": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"Attachments": {
				"dataValueType": Terrasoft.DataValueType.COLLECTION,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"isCollection": true
			},
			"FileSchemaName": {
				"dataValueType": Terrasoft.DataValueType.CUSTOM_OBJECT,
				"value": "ActivityFile"
			},

			"Status": {
				"type": this.Terrasoft.ViewModelColumnType.ENTITY_COLUMN,
				"lookupListConfig": {
					"filter": function() {
						return this.getStatusFilters();
					},
					"columns": ["Finish"]
				},
				"dependencies": [
					{
						"columns": ["Status"],
						"methodName": "onStatusChanged"
					}
				]
			},
			"InteractionWithManager": {
				"lookupListConfig": {
					"columns": ["MeetingDateTime", "QuarterlyCheckInDate"]
				}
			},
			"IsAnnualReview": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"IsSendToEmployeeForRevision": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"IsTransferAnnualReviewToMeeting": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"IsFinishAnnualReview": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"IsFinishPerformanceReview": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"IsCheckInDateVisible": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			},
			"IsCompletedAndSelfImplementation": {
				"dataValueType": Terrasoft.DataValueType.BOOLEAN,
				"type": Terrasoft.ViewModelColumnType.VIRTUAL_COLUMN,
				"value": false
			}
		},
		mixins: {
			OpportunityPartnerWinnerMixin: "Terrasoft.OpportunityPartnerWinnerMixin",
			SACaseModalBoxMixin: "Terrasoft.configuration.mixins.SACaseModalBoxMixin",
			WorkActivityPageMixin: "Terrasoft.configuration.mixins.WorkActivityPageMixin"
		},
		methods: {
			init: function() {
				this.callParent(arguments);
				this.$Attachments = this.Ext.create("Terrasoft.BaseViewModelCollection");
			},

			onEntityInitialized: function() {
				this.callParent(arguments);
				this.initIsOpenEditModeVisible();
				this.initActivityAttributeValues();
			},

			validate: function() {
				var isValid = this.callParent(arguments);
				if (!isValid) {
					return isValid;
				}
				if (this.isNeedToSelectPartner()) {
					this.close();
					this.openSetRecommendedPartnerMiniPage();
					return false;
				} else if (this.isNeedToSelectWinner()) {
					this.sandbox.publish("NeedToSelectOpportunityPartnerWinner", {
						activityId: this.$Id
					});
					this.close();
					return false;
				} else {
					return isValid;
				}
			},

			onStatusChanged: function() {
				this.callParent(arguments);
				this.initIsCompletedAndSelfImplementation();
			},

			initIsOpenEditModeVisible: function() {
				this.$IsOpenEditModeVisible = this.isEditable()
					&& !(this.getIsFeatureEnabled("UseSelectRecommendedPartner")
							&& this.getLookupValue("Kind") === WorkPRMBaseConstants.ActivityKind.ConvertLead
							&& !this.isEmpty(this.$Lead)
							&& this.isEmpty(this.$Lead.Partner));
			},

			isNeedToSelectPartner: function() {
				return this.getIsFeatureEnabled("UseSelectRecommendedPartner")
					&& this.getLookupValue("Kind") === WorkPRMBaseConstants.ActivityKind.ConvertLead
					&& !this.isEmpty(this.$Opportunity);
			},

			openSetRecommendedPartnerMiniPage: function() {
				var valuePairs = [];
				valuePairs.push({
					name: "ActivityId",
					value: this.$PrimaryColumnValue
				}, {
					name: "ActivityComment",
					value: this.$DetailedResult
				});
				const config = {
					entitySchemaName: "Opportunity",
					isFixed: true,
					operation: Terrasoft.ConfigurationEnums.CardOperation.EDIT,
					showDelay: 0,
					miniPageSchemaName: "RecommendedPartnerMiniPage",
					recordId: this.getLookupValue("Opportunity"),
					valuePairs: valuePairs
				};
				this.openMiniPage(config);
			},

			getIsMeetingDateAndTimeActivity: function () {
				return this.getLookupValue("Kind") === WorkPRMBaseConstants.ActivityKind.MeetingDateAndTime;
			},

			onProcessResultChanged: function (model, value) {
				if (!this.get("IsEntityInitialized")) {
					return;
				}
				this.set("IsStartDateVisible", this.getIsMeetingDateAndTimeActivity() && value?.value === WorkPRMBaseConstants.ActivityResult.MeetingScheduled);
				this.initActivityAttributeValues();
			},

			onResultChanged: function () {
				this.callParent(arguments);
				if (!this.get("IsEntityInitialized")) {
					return;
				}
				this.initActivityAttributeValues();
			},

			onActivityCategoryChanged: function () {
				if (!this.get("IsEntityInitialized")) {
					return;
				}
				this.initActivityAttributeValues();
				if (this.getIsArProcessOrAnnualReview() && this.getLookupValue("Status") === WorkPRMBaseConstants.ActivityStatus.Canceled) {
